import logging
from jsilib.jsonrpc.exc import ClientClosedError

from taf.fdsw.rc.clients.exceptions import TimeoutExceeded
from taf.fdsw.rc.interfaces.FDSW18SP.swm import Package
from taf.fdsw.rc.interfaces.FDSW22A.swm import SoftwareManagement22A
from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.schemas.FDSW18SP.swm import SoftwareUpdateStatus
from taf.fdsw.rc.schemas.FDSW23B.swm import RunningSofware23B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SoftwareManagement23B(SoftwareManagement22A):

    def __init__(self, client):
        super(SoftwareManagement23B, self).__init__(client)

    def get_all_software_inventory(self, timeout=10):
        all_sw_inventory = self._client.send(
            method='software.fetch',
            parameters={},
            timeout=timeout
        )
        sw_inventory = RunningSofware23B.from_object_dict(all_sw_inventory.data)
        return sw_inventory

    def software_rollback(self, sw_slot_id, timeout=10, **kwargs):
        reset_type = kwargs.get('reset_type', None)
        try:
            self._client.send(
                method='software.rollback',
                timeout=timeout,
                parameters={"slotId": str(sw_slot_id), "resetType": reset_type})
        except (TimeoutExceeded, ClientClosedError):
            # ClientClosedError is raised from within jsilib when response is not provided in time
            logger.info('Connection closed due to rollback operation')
        finally:
            self._client.disconnect()

    def software_update(self, sw_pkg_path, activate=False, timeout=360, **kwargs):
        package = Package(sw_pkg_path)
        logger.debug("Subscribing for notifications")
        self._client.subscribe_for_notifications(method='software')

        targetBD = self._get_targetBD_file(package)
        initialized_update_status = self.initialize_sw_update(targetBD, timeout, **kwargs)
        self._upload_files_to_sw_update(package, initialized_update_status, timeout)
        self.last_targetBD = targetBD
        self.last_package = package

        logger.info('Software upload succeeded.')

        activation_options = kwargs.get('activation_options', [])
        activation_params = {'activation': activate,
                             'activationOptions': activation_options}
        is_activation_successful = self._finish_update(activation_params)
        if is_activation_successful and activate:
            self._client.disconnect()
            logger.info('Node B reset ... closing connection')
        elif not is_activation_successful:
            self._client.disconnect()
            raise OperationFailure('Software activation failed ... closing connection')
        else:
            logger.info('Software update succeeded.')

    def initialize_sw_update(self, targetBD, timeout, **kwargs):
        logger.info('Starting software update')
        resp = self._client.send(
            method='software.startUpdating',
            parameters=None,
            payload=targetBD,
            timeout=timeout
        )
        self._check_sw_update_response(resp)
        targetBD_update_status = SoftwareUpdateStatus.from_object_dict(resp.data)
        logger.info('TargetBD file sent. Starting sending other files')
        return targetBD_update_status

    def _finish_update(self, activation_options):
        resp = self._client.send(
            method='software.finishUpdating',
            parameters=activation_options,
            payload=None)
        if resp.status is False:
            logger.info('Software activation failed with {}'.format(resp.error))
            return False
        return True

    def get_available_reset_options(self, slot_id, timeout):
        sw_info = self.get_all_software_inventory(timeout=timeout)
        for slot in sw_info.slots:
            if slot.id == str(slot_id):
                return slot.supported_config_reset_options
